async function draft(c,kind,payload,plan=null,state='pending'){const {sqlDriver:s,scope,actor,req}=c;const r=await req().input('flow',s.NVarChar(20),scope.flow).input('kind',s.NVarChar(30),kind).input('payload',s.NVarChar(s.MAX),JSON.stringify(payload)).input('plan',s.NVarChar(s.MAX),plan?JSON.stringify(plan):null).input('state',s.NVarChar(20),state).input('actor',s.BigInt,actor.id).query('INSERT dbo.test_daily_drafts(flow,kind,state,payload_json,plan_json,created_by)VALUES(@flow,@kind,@state,@payload,@plan,@actor);SELECT CAST(SCOPE_IDENTITY() AS bigint) id;');return {id:Number(r.recordset[0].id),state,kind,payload,plan};}
async function mark(c,id,state,result,reason=null){await c.req().input('id',c.sqlDriver.BigInt,id).input('state',c.sqlDriver.NVarChar(20),state).input('result',c.sqlDriver.NVarChar(c.sqlDriver.MAX),JSON.stringify(result)).input('actor',c.sqlDriver.BigInt,c.actor.id).input('reason',c.sqlDriver.NVarChar(500),reason).query('UPDATE dbo.test_daily_drafts SET state=@state,result_json=@result,decided_by=@actor,reason=@reason WHERE id=@id');await writeAuditLog(c.req(),{actor:c.actor,action:'test_daily_'+state,entityType:'test_daily_draft',entityId:id,afterSnapshot:result,reason});}
