export async function dailyContext(flow,actor){return atomic(flow,actor,async c=>{const {req,scope:s,sqlDriver:q}=c;const drafts=(await req().input('f',q.NVarChar(20),flow).query(c.copyContext?`SELECT d.* FROM dbo.test_daily_drafts d WHERE d.flow=@f AND EXISTS(SELECT 1 FROM dbo.stage4_copy_requests j WHERE j.copy_id=CONVERT(uniqueidentifier,N'${c.copyContext.copyId}') AND j.operation IN(N'stock_count_draft',N'purchase_return_draft') AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.id'))=d.id) ORDER BY d.id`:'SELECT * FROM dbo.test_daily_drafts WHERE flow=@f ORDER BY id')).recordset;const accounts=c.copyContext?[]:(await req().input('f',q.NVarChar(20),flow).query('SELECT a.* FROM dbo.finance_accounts a JOIN dbo.test_daily_accounts t ON t.account_id=a.id WHERE t.flow=@f ORDER BY a.id')).recordset;let party=null;if(s.customer_id)party=(await req().input('id',q.BigInt,s.customer_id).query('SELECT id,customer_code code,name,currency_code,balance FROM dbo.customers WHERE id=@id')).recordset[0];if(s.supplier_id)party=(await req().input('id',q.BigInt,s.supplier_id).input('partyAccount',q.BigInt,s.supplier_account_id??null).query(s.supplier_account_id?'SELECT s.id,s.supplier_code code,s.name,a.currency_code,a.current_balance balance FROM dbo.suppliers s JOIN dbo.party_currency_accounts a ON a.id=@partyAccount AND a.supplier_id=s.id AND a.party_entity_id=s.party_entity_id AND a.customer_id IS NULL WHERE s.id=@id':'SELECT id,supplier_code code,name,currency_code,balance FROM dbo.suppliers WHERE id=@id')).recordset[0];let source=null,items=[];if(s.source_id){source=(await req().input('id',q.BigInt,s.source_id).query(`SELECT id,document_no,status,document_currency,grand_total FROM dbo.${s.source_kind}_invoices WHERE id=@id`)).recordset[0];items=(await req().input('id',q.BigInt,s.source_id).query(`SELECT id,product_id,quantity,line_total FROM dbo.${s.source_kind}_invoice_items WHERE ${s.source_kind}_invoice_id=@id ORDER BY id`)).recordset;}const availablePurchaseSources=flow==='purchase'?await purchaseReturnSources(c,drafts):[],countProducts=flow==='count'?await countProductScope(c):[];const value=projectPersonnelDailyContext(flow,actor,{scope:s,drafts,accounts,party,source,items,availablePurchaseSources,countProducts,movementFingerprint:['count','count-cancel'].includes(flow)?hash(await fingerprint(c)):null});return c.copyContext?{...value,meta:contextCopyMeta(c),operationOrigin:c.copyContext.operationOrigin}:value;},{write:false});}


async function fxPayload(c,i){office(c);if(Object.keys(i).some(k=>!['requestId','customerId','accountId','amount','currency','documentDate','description'].includes(k)))fail('TEST_PAYLOAD','Kur ve yetki sunucudan alınır.');if(Number(i.customerId)!==Number(c.scope.customer_id))fail('TEST_SCOPE','Yeni TEST USD carisi gerekli.',403);validDate(i.documentDate);const amount=Number(i.amount);if(!Number.isFinite(amount)||amount<=0||amount>500||Math.abs(amount*100-Math.round(amount*100))>1e-7)fail('AMOUNT','0–500 arası iki ondalık tutar gerekli.');const a=await account(c,i.currency);if(!a||Number(a.id)!==Number(i.accountId))fail('TEST_ACCOUNT','Aynı dövizli tanımlı TEST hesabı gerekli.',403);return {...i,amount,customerId:Number(c.scope.customer_id),accountId:Number(a.id),paymentMethod:a.account_type};}
