export async function dailyFxCollect(i,actor){return atomic('fx',actor,c=>journal(c,i,'collection',async()=>{const p=await fxPayload(c,i);const rateEvidence=(await c.req().input('date',c.sqlDriver.Date,p.documentDate).query("WITH rates AS(SELECT id,currency_code,rate_to_try,rate_date,source,created_at,ROW_NUMBER()OVER(PARTITION BY currency_code ORDER BY rate_date DESC,id DESC)n FROM dbo.currency_rates WITH(HOLDLOCK) WHERE rate_date<=@date AND currency_code IN(N'USD',N'EUR')) SELECT id,currency_code,rate_to_try,rate_date,source,created_at FROM rates WHERE n=1")).recordset;const result=await createCustomerCollection(p,actor,{...c,linkedInvoiceId:null});return {...result,rateEvidence,settlementRule:'document amount × document TRY rate / customer TRY rate; 4 decimals',capturedAt:new Date().toISOString()};}));}
